function prevPeriod(startDate, endDate) {
  const start = new Date(startDate);
  const end = new Date(endDate);
  const days = Math.round((end.getTime() - start.getTime()) / 864e5) + 1;
  const pEnd = new Date(start.getTime() - 864e5);
  const pStart = new Date(pEnd.getTime() - (days - 1) * 864e5);
  return {
    startDate: pStart.toISOString().slice(0, 10),
    endDate: pEnd.toISOString().slice(0, 10)
  };
}
