async function discoverAndStoreProperties(orgId3) {
  const token = await getValidToken(orgId3).catch(() => null);
  if (!token) return 0;
  const existing = await getStoredProperty(orgId3);
  if (existing) return 1;
  try {
    const data = await ga4AdminGet(token, "/accounts");
    let count = 0;
    let firstProperty = null;
    for (const account of (data.accounts ?? []).slice(0, 5)) {
      const propsData = await ga4AdminGet(token, `/properties?filter=parent:${account.name}`).catch(() => ({ properties: [] }));
      const props = propsData.properties ?? [];
      count += props.length;
      if (!firstProperty && props[0]) firstProperty = props[0];
    }
    if (firstProperty) {
      const propertyId = firstProperty.name.split("/")[1] ?? firstProperty.name;
      await setStoredProperty(orgId3, propertyId, firstProperty.displayName ?? propertyId);
      logger.info({ orgId: orgId3, propertyId }, "[ga4] auto-activated first discovered property");
    }
    return count;
  } catch (e) {
    logger.warn({ e, orgId: orgId3 }, "[ga4] discoverAndStoreProperties failed");
    return 0;
  }
}
async function getGA4Overview(orgId3, startDate, endDate) {
  const EMPTY2 = { rows: [], totals: [] };
  const ctx = await getGA4Context(orgId3);
  if (!ctx) return EMPTY2;
  const metrics = [
    "sessions",
    "totalUsers",
    "newUsers",
    "bounceRate",
    "engagementRate",
    "averageSessionDuration",
    "screenPageViews",
    "conversions"
  ].map((n) => ({ name: n }));
  const prev = prevPeriod(startDate, endDate);
  try {
    const [daily, curTotals, prevTotals] = await Promise.all([
      // Daily breakdown for sparkline chart
      ga4Post(ctx.token, ctx.propertyId, ":runReport", {
        dateRanges: [{ startDate, endDate }],
        dimensions: [{ name: "date" }],
        metrics,
        orderBys: [{ dimension: { dimensionName: "date" }, desc: false }]
      }),
      // Current period totals
      ga4Post(ctx.token, ctx.propertyId, ":runReport", {
        dateRanges: [{ startDate, endDate }],
        metrics,
        returnPropertyQuota: false
      }),
      // Previous period totals for comparison
      ga4Post(ctx.token, ctx.propertyId, ":runReport", {
        dateRanges: [{ startDate: prev.startDate, endDate: prev.endDate }],
        metrics,
        returnPropertyQuota: false
      })
    ]);
    const buildTotals = (report) => {
      if (report.totals?.[0]?.metricValues) return report.totals[0].metricValues;
      if (!report.rows?.length) return metrics.map(() => ({ value: "0" }));
      const sums = metrics.map(() => 0);
      for (const row of report.rows) {
        row.metricValues?.forEach((mv, i) => {
          sums[i] = (sums[i] ?? 0) + parseFloat(mv.value ?? "0");
        });
      }
      return sums.map((v) => ({ value: String(Math.round(v * 1e4) / 1e4) }));
    };
    return {
      rows: daily.rows ?? [],
      totals: [
        { metricValues: buildTotals(curTotals) },
        { metricValues: buildTotals(prevTotals) }
      ]
    };
  } catch (e) {
    logger.warn({ e, orgId: orgId3 }, "[ga4] getGA4Overview failed");
    return EMPTY2;
  }
}
