// src/services/ai-quota.ts
function buildQuotaGuidance(_creditCheck, aiPrefs, plan4) {
  const intensity = aiPrefs.aiIntensity ?? "\xC9quilibr\xE9";
  const p = (plan4 ?? "standard").toLowerCase();
  let action;
  let ctaLabel;
  let ctaUrl;
  if (intensity !== "Conservateur") {
    action = "change_mode";
    ctaLabel = "Passer en mode Conservateur pour \xE9conomiser les cr\xE9dits";
    ctaUrl = "/settings?tab=ai";
  } else if (p === "ultra") {
    action = "buy_credits";
    ctaLabel = "Acheter des cr\xE9dits IA suppl\xE9mentaires";
    ctaUrl = "/settings?tab=billing&addon=ai_credits";
  } else if (p === "pro") {
    action = "upgrade_plan";
    ctaLabel = "Passer en Ultra pour des cr\xE9dits illimit\xE9s";
    ctaUrl = "/settings?tab=billing";
  } else {
    action = "upgrade_plan";
    ctaLabel = "Passer en Pro pour plus de cr\xE9dits IA";
    ctaUrl = "/settings?tab=billing";
  }
  return {
    code: "QUOTA_EXCEEDED",
    error: "Cr\xE9dits IA insuffisants pour ce mois",
    guidance: { action, ctaLabel, ctaUrl }
  };
}

