router18.patch("/missions/:id", canWrite, async (req, res) => {
  try {
    const db15 = orgDb3(req);
    const org16 = orgId(req);
    const id = String(req.params.id);
    const existing = await db15(`SELECT * FROM missions WHERE id = $1 AND org_id = $2`, [id, org16]);
    if (!existing.rows[0]) {
      res.status(404).json({ error: "Mission not found" });
      return;
    }
    const prev = existing.rows[0];
    const {
      title,
      description,
      status,
      impact,
      effort,
      category,
      priority,
      steps,
      dueDate,
      priorityScore,
      assignedTo
    } = req.body;
    const newStatus = status || prev.status;
    const isNowDone = newStatus === "done" && prev.status !== "done";
    const isNowDismissed = newStatus === "dismissed" && prev.status !== "dismissed";
    await db15(`
      UPDATE missions SET
        title        = COALESCE($1, title),
        description  = COALESCE($2, description),
        status       = $3,
        impact       = COALESCE($4, impact),
        effort       = COALESCE($5, effort),
        category     = COALESCE($6, category),
        priority     = COALESCE($7, priority),
        steps        = COALESCE($8::jsonb, steps),
        due_date     = COALESCE($9, due_date),
        priority_score = COALESCE($10, priority_score),
        assigned_to  = COALESCE($11, assigned_to),
        completed_at = CASE WHEN $12 THEN NOW() ELSE completed_at END,
        dismissed_at = CASE WHEN $13 THEN NOW() ELSE dismissed_at END,
        updated_at   = NOW()
      WHERE id = $14 AND org_id = $15
    `, [
      title || null,
      description || null,
      newStatus,
      impact || null,
      effort || null,
      category || null,
      priority || null,
      steps ? JSON.stringify(steps) : null,
      dueDate || null,
      priorityScore ? Number(priorityScore) : null,
      assignedTo || null,
      isNowDone,
      isNowDismissed,
      id,
      org16
    ]);
    const row = await db15(`SELECT * FROM missions WHERE id = $1 AND org_id = $2`, [id, org16]);
    const mission = rowToMission(row.rows[0]);
    if (newStatus !== prev.status) {
      await logHistory(db15, id, org16, "status_changed", prev.status, newStatus);
      if (isNowDone) {
        await store.logActivity({
          type: "report",
          label: `Mission accomplie : ${prev.title}`,
          targetId: id,
          targetType: "mission",
          metadata: { category: prev.category, impact: prev.impact },
          orgId: org16,
          actionKey: "activity.mission.done",
          actionParams: { title: String(prev.title) },
          userId: req.orgContext?.userId || req.orgContext?.email,
          userName: req.orgContext?.name || req.orgContext?.email
        }).catch(() => {
        });
      }
    }
    res.json(mission);
  } catch (err) {
    logger.error({ err }, "[Missions] PATCH error");
    res.status(500).json({ error: "Database error" });
  }
});
