function withCache(ttlSeconds) {
  return (req, res, next) => {
    const orgId3 = req.orgId ?? "anon";
    const key = `${orgId3}:${req.originalUrl || req.url}`;
    const now = Date.now();
    const hit = _cache3.get(key);
    if (hit && now - hit.ts < ttlSeconds * 1e3) {
      res.setHeader("X-Cache", "HIT");
      res.json(hit.data);
      return;
    }
    const _origJson = res.json.bind(res);
    res.json = (body) => {
      _cache3.set(key, { ts: now, data: body });
      res.setHeader("X-Cache", "MISS");
      return _origJson(body);
    };
    next();
  };
}

