router32.post("/integrations/webhooks/test", requireAddon("advancedWebhooks", "Advanced Webhooks"), async (req, res) => {
  const { url } = req.body;
  if (!url) {
    res.status(400).json({ error: "url requis" });
    return;
  }
  let parsed2;
  try {
    parsed2 = new URL(url);
  } catch {
    res.status(400).json({ error: "URL invalide" });
    return;
  }
  if (parsed2.protocol !== "https:") {
    res.status(400).json({ error: "HTTPS uniquement" });
    return;
  }
  const hostname = parsed2.hostname.toLowerCase();
  const blocked = ["localhost", "127.0.0.1", "::1", "0.0.0.0", "[::1]"];
  if (blocked.includes(hostname)) {
    res.status(400).json({ error: "Adresse interdite" });
    return;
  }
  if (hostname.endsWith(".local") || hostname.endsWith(".internal") || /^10\./.test(hostname) || /^192\.168\./.test(hostname) || /^172\.(1[6-9]|2[0-9]|3[01])\./.test(hostname)) {
    res.status(400).json({ error: "Adresse priv\xE9e interdite" });
    return;
  }
  try {
    const ac = new AbortController();
    const to = setTimeout(() => ac.abort(), 8e3);
    const r = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json", "User-Agent": "FlowPoint-Webhook-Test/1.0" },
      body: JSON.stringify({ event: "ping", ts: Date.now(), source: "flowpoint-test" }),
      signal: ac.signal,
      redirect: "error"
    });
    clearTimeout(to);
    res.json({ ok: r.ok, url, statusCode: r.status, durationMs: 0, note: r.ok ? "Ping OK" : "Endpoint a renvoy\xE9 une erreur" });
  } catch (err) {
    res.json({ ok: false, url, error: safeErrMsg(err), note: "Test indisponible \u2014 enregistrez le webhook" });
  }
});
